const t="";async function e(){const r=await fetch(`${t}/api/blog`);if(!r.ok)throw new Error("Erreur chargement blog");return r.json()}async function a(r){const o=await fetch(`${t}/api/blog/${r}`);if(!o.ok)throw new Error("Article non trouvé");return o.json()}async function s(r){const o=await fetch(`${t}/api/forms`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});if(!o.ok){const n=await o.json().catch(()=>({}));throw new Error(n.error||"Erreur envoi formulaire")}return o.json()}export{e as a,a as g,s};
